using Microsoft.AspNetCore.Mvc;
using RaceDayNova.Mvc.Models;
using RaceDayNova.Mvc.Services;
namespace RaceDayNova.Mvc.Controllers;
public class OrganiserController(ApiClient api) : Controller
{
    private bool Allowed() => HttpContext.Session.GetString("UserRole") == "Organiser";
    private IActionResult Guard() => RedirectToAction("Login", "Auth");
    public async Task<IActionResult> Index() { if (!Allowed()) return Guard(); var r = await api.Get<List<EventDto>>("api/events?organiserId=" + HttpContext.Session.GetInt32("UserId")); ViewBag.Error = r.Error; var events = r.Data ?? new(); ViewBag.TotalEvents = events.Count; ViewBag.Upcoming = events.Count(e => e.EventDate >= DateOnly.FromDateTime(DateTime.Today) && e.EventStatus != "Cancelled"); ViewBag.TotalDistance = events.Sum(e => e.DistanceKm); var counts = new Dictionary<int, int>(); foreach (var ev in events) { var entries = await api.Get<List<EnrolmentDto>>($"api/events/{ev.EventId}/enrolments"); counts[ev.EventId] = entries.Data?.Count ?? 0; } ViewBag.EnrolmentCounts = counts; return View(events); }
    public async Task<IActionResult> Events() { if (!Allowed()) return Guard(); var r = await api.Get<List<EventDto>>("api/events?organiserId=" + HttpContext.Session.GetInt32("UserId")); ViewBag.Error = r.Error; return View(r.Data ?? new()); }
    [HttpGet] public IActionResult CreateEvent() { if (!Allowed()) return Guard(); return View("EventForm", new EventFormModel { EventDate = DateOnly.FromDateTime(DateTime.Today.AddDays(14)), StartTime = new TimeOnly(7,0), EventType = "Running", DistanceKm = 5 }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateEvent(EventFormModel model) => await SaveEvent(model, false);
    [HttpGet] public async Task<IActionResult> EditEvent(int id) { if (!Allowed()) return Guard(); var r = await api.Get<EventDto>($"api/events/{id}"); if (r.Data == null) { TempData["Error"] = r.Error ?? "Event not found."; return RedirectToAction(nameof(Events)); } var e = r.Data; return View("EventForm", new EventFormModel { EventId=e.EventId, EventName=e.EventName, EventType=e.EventType, EventDate=e.EventDate, StartTime=e.StartTime, Venue=e.Venue, City=e.City, Province=e.Province, DistanceKm=e.DistanceKm, Description=e.Description, RouteReference=e.RouteReference, EventStatus=e.EventStatus, BannerImageUrl=e.BannerImageUrl }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> EditEvent(EventFormModel model) => await SaveEvent(model, true);
    private async Task<IActionResult> SaveEvent(EventFormModel model, bool edit)
    {
        if (!Allowed()) return Guard(); if (!ModelState.IsValid) return View("EventForm", model);
        var payload = new { model.EventName, model.EventType, model.EventDate, model.StartTime, model.Venue, model.City, model.Province, model.DistanceKm, model.Description, model.RouteReference, model.EventStatus, model.BannerImageUrl };
        var result = edit ? await api.Put<EventDto>($"api/events/{model.EventId}", payload) : await api.Post<EventDto>("api/events", payload);
        if (result.Data == null) { ModelState.AddModelError(string.Empty, result.Error ?? "The event could not be saved."); return View("EventForm", model); }
        if (model.BannerImage != null && model.BannerImage.Length > 0) { var upload = await api.Upload($"api/events/{result.Data.EventId}/banner", model.BannerImage); if (upload.Url != null) { result.Data.BannerImageUrl = upload.Url; await api.Put<EventDto>($"api/events/{result.Data.EventId}", new { result.Data.EventName, result.Data.EventType, result.Data.EventDate, result.Data.StartTime, result.Data.Venue, result.Data.City, result.Data.Province, result.Data.DistanceKm, result.Data.Description, result.Data.RouteReference, result.Data.EventStatus, result.Data.BannerImageUrl }); } else { TempData["Error"] = "Event saved, but image upload failed: " + upload.Error; } }
        TempData["Success"] = edit ? "Event updated successfully." : "Event created successfully."; return RedirectToAction(nameof(Events));
    }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteEvent(int id) { if (!Allowed()) return Guard(); var r = await api.Delete($"api/events/{id}"); TempData[r.Ok ? "Success" : "Error"] = r.Ok ? "Event deleted or cancelled." : r.Error; return RedirectToAction(nameof(Events)); }
    public async Task<IActionResult> Categories() { if (!Allowed()) return Guard(); var r = await api.Get<List<CategoryDto>>("api/categories"); ViewBag.Error = r.Error; return View(r.Data ?? new()); }
    [HttpGet] public IActionResult CreateCategory() { if (!Allowed()) return Guard(); return View("CategoryForm", new CategoryFormModel()); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> CreateCategory(CategoryFormModel model) { if (!Allowed()) return Guard(); if (!ModelState.IsValid) return View("CategoryForm", model); var r = await api.Post<CategoryDto>("api/categories", new { model.CategoryName, model.AgeFrom, model.AgeTo, model.CategoryNote }); if (r.Data == null) { ModelState.AddModelError("", r.Error ?? "Could not create category."); return View("CategoryForm", model); } TempData["Success"] = "Category created."; return RedirectToAction(nameof(Categories)); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> DeleteCategory(int id) { if (!Allowed()) return Guard(); var r = await api.Delete($"api/categories/{id}"); TempData[r.Ok ? "Success" : "Error"] = r.Ok ? "Category deleted." : r.Error; return RedirectToAction(nameof(Categories)); }
    public async Task<IActionResult> EventCategories(int id) { if (!Allowed()) return Guard(); var ev = await api.Get<EventDto>($"api/events/{id}"); var all = await api.Get<List<CategoryDto>>("api/categories"); var attached = await api.Get<List<EventCategoryDto>>($"api/events/{id}/categories"); ViewBag.EventName = ev.Data?.EventName ?? "Event"; ViewBag.Categories = all.Data ?? new(); ViewBag.Attached = attached.Data ?? new(); ViewBag.EventId = id; ViewBag.Error = ev.Error ?? all.Error ?? attached.Error; return View(); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> AddEventCategory(int id, int categoryId, decimal entryFee, int? placesAvailable) { if (!Allowed()) return Guard(); var r = await api.Post<EventCategoryDto>($"api/events/{id}/categories", new { CategoryId = categoryId, EntryFee = entryFee, PlacesAvailable = placesAvailable }); TempData[r.Data != null ? "Success" : "Error"] = r.Data != null ? "Category added to event." : r.Error ?? "Could not attach category."; return RedirectToAction(nameof(EventCategories), new { id }); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> RemoveEventCategory(int id, int categoryId) { if (!Allowed()) return Guard(); var r = await api.Delete($"api/events/{id}/categories/{categoryId}"); TempData[r.Ok ? "Success" : "Error"] = r.Ok ? "Category removed from event." : r.Error; return RedirectToAction(nameof(EventCategories), new { id }); }
    public async Task<IActionResult> Enrolments(int id) { if (!Allowed()) return Guard(); var r = await api.Get<List<EnrolmentDto>>($"api/events/{id}/enrolments"); ViewBag.EventId = id; ViewBag.Error = r.Error; return View(r.Data ?? new()); }
    public async Task<IActionResult> Results(int id) { if (!Allowed()) return Guard(); var r = await api.Get<List<EnrolmentDto>>($"api/events/{id}/enrolments"); ViewBag.EventId = id; ViewBag.Error = r.Error; return View(r.Data ?? new()); }
    [HttpPost, ValidateAntiForgeryToken] public async Task<IActionResult> SaveResult(int id, int enrolmentId, int? positionNo, string? finishTime, string resultStatus = "Finished") { if (!Allowed()) return Guard(); TimeSpan? time = TimeSpan.TryParse(finishTime, out var parsed) ? parsed : null; var r = await api.Post<object>($"api/enrolments/{enrolmentId}/result", new { PositionNo = positionNo, FinishTime = time, ResultStatus = resultStatus }); TempData[r.Error == null ? "Success" : "Error"] = r.Error ?? "Result saved."; return RedirectToAction(nameof(Results), new { id }); }
}
